-- Generated from PF2e 8.6.1 NPC compendium headers. Not stat blocks.
BEGIN;
ALTER TABLE pf2e_catalog_entries DROP CONSTRAINT IF EXISTS pf2e_catalog_entries_item_kind_check;
ALTER TABLE pf2e_catalog_entries ADD CONSTRAINT pf2e_catalog_entries_item_kind_check CHECK (item_kind = ANY (ARRAY['feat','classfeature','action','heritage','class','ancestry','background','spell','equipment','ancestryfeature','deity','familiarability','boon','adventureaction','condition','npc']));
CREATE TABLE IF NOT EXISTS pf2e_bestiary_headers (
  entry_id bigint PRIMARY KEY REFERENCES pf2e_catalog_entries(entry_id) ON DELETE CASCADE,
  compendium_collection text NOT NULL,
  foundry_document_id text NOT NULL,
  pack_label text NOT NULL,
  rarity text,
  size text,
  hp integer,
  ac integer,
  source_url text NOT NULL,
  UNIQUE (compendium_collection, foundry_document_id)
);
CREATE TEMP TABLE _npc (
  pf2e_name text, pf2e_slug text, compendium_collection text, source_path text,
  traits text, level integer, pf2e_source_book text,
  foundry_document_id text, pack_label text, rarity text, size text,
  hp integer, ac integer, source_url text
) ON COMMIT DROP;
SELECT 'pf2e-remaster','npc','npc',pf2e_name,pf2e_slug,compendium_collection,source_path,NULL,NULLIF(traits,''),level,pf2e_source_book FROM _npc
ON CONFLICT (ruleset_id,compendium_collection,source_path) DO UPDATE SET item_kind=EXCLUDED.item_kind,foundry_type=EXCLUDED.foundry_type,pf2e_name=EXCLUDED.pf2e_name,pf2e_slug=EXCLUDED.pf2e_slug,traits=EXCLUDED.traits,level=EXCLUDED.level,pf2e_source_book=EXCLUDED.pf2e_source_book;
SELECT e.entry_id,n.foundry_document_id,n.pack_label,n.rarity,n.size,n.hp,n.ac,n.source_url,n.compendium_collection
FROM _npc n JOIN pf2e_catalog_entries e ON e.ruleset_id='pf2e-remaster' AND e.compendium_collection=n.compendium_collection AND e.source_path=n.source_path
ON CONFLICT (entry_id) DO UPDATE SET foundry_document_id=EXCLUDED.foundry_document_id,pack_label=EXCLUDED.pack_label,rarity=EXCLUDED.rarity,size=EXCLUDED.size,hp=EXCLUDED.hp,ac=EXCLUDED.ac,source_url=EXCLUDED.source_url,compendium_collection=EXCLUDED.compendium_collection;
COMMIT;
